package com.posthog.android.internal

import android.view.View
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.node.RootForTest
import androidx.compose.ui.semantics.AccessibilityAction
import androidx.compose.ui.semantics.Role
import androidx.compose.ui.semantics.SemanticsActions
import androidx.compose.ui.semantics.SemanticsConfiguration
import androidx.compose.ui.semantics.SemanticsNode
import androidx.compose.ui.semantics.SemanticsOwner
import androidx.compose.ui.semantics.SemanticsProperties
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.posthog.android.PostHogAutocaptureNoCapture
import com.posthog.android.replay.PostHogMaskModifier.PostHogReplayMask
import org.junit.runner.RunWith
import org.mockito.Mockito
import org.mockito.kotlin.mock
import org.mockito.kotlin.whenever
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

@RunWith(AndroidJUnit4::class)
internal class ComposeInteractionTargetResolverTest {
    private val view = Mockito.mock(View::class.java, Mockito.withSettings().extraInterfaces(RootForTest::class.java))
    private val owner = mock<SemanticsOwner>()
    private val rootConfig = SemanticsConfiguration()
    private val buttonConfig =
        SemanticsConfiguration().apply {
            this[SemanticsActions.OnClick] = AccessibilityAction(null) { true }
            this[SemanticsProperties.Role] = Role.Button
            this[SemanticsProperties.TestTag] = "checkout_button"
        }
    private val childConfig = SemanticsConfiguration()
    private val child = node(3, childConfig)
    private val button = node(2, buttonConfig, listOf(child))
    private val root = node(1, rootConfig, listOf(button))

    init {
        whenever((view as RootForTest).semanticsOwner).thenReturn(owner)
        whenever(owner.unmergedRootSemanticsNode).thenReturn(root)
        whenever(button.parent).thenReturn(root)
        whenever(child.parent).thenReturn(button)
    }

    private fun node(
        id: Int,
        config: SemanticsConfiguration,
        children: List<SemanticsNode> = emptyList(),
    ): SemanticsNode =
        mock<SemanticsNode>().also {
            whenever(it.id).thenReturn(id)
            whenever(it.config).thenReturn(config)
            whenever(it.children).thenReturn(children)
            whenever(it.boundsInWindow).thenReturn(Rect(0f, 0f, 100f, 100f))
        }

    private fun resolve(): InteractionTarget? = ComposeInteractionTargetResolver.resolve(view, 20f, 20f, emptyList())

    @Test
    fun `semantic role test tag and nearest actionable ancestor are captured without labels`() {
        childConfig[SemanticsProperties.ContentDescription] = listOf("Never serialized")
        val target = assertNotNull(resolve())
        assertEquals(2, target.semanticsId)
        assertEquals(InteractionElement("button", "checkout_button"), target.elements.first())
        assertEquals(setOf("tag_name", "attr__id", "nth_child", "nth_of_type"), target.elements.first().properties().keys)
    }

    @Test
    fun `unmerged ignored child blocks actionable parent and dynamic false restores capture`() {
        childConfig[PostHogAutocaptureNoCapture] = true
        assertNull(resolve())
        childConfig[PostHogAutocaptureNoCapture] = false
        assertNotNull(resolve())
        rootConfig[PostHogAutocaptureNoCapture] = true
        assertNull(resolve())
    }

    @Test
    fun `replay mask and password semantics exclude entire subtree`() {
        rootConfig[PostHogReplayMask] = true
        assertNull(resolve())
        rootConfig[PostHogReplayMask] = false
        assertNotNull(resolve())
        childConfig[SemanticsProperties.Password] = Unit
        assertNull(resolve())
    }

    @Test
    fun `Compose exclusion also gates native AndroidView interop`() {
        val native = InteractionTarget(view, elements = listOf(InteractionElement("button", "native_button")))
        val layout = mock<androidx.compose.ui.layout.LayoutInfo>()
        whenever(child.layoutInfo).thenReturn(layout)
        assertEquals(native, ComposeInteractionTargetResolver.resolve(view, 20f, 20f, emptyList(), native, layout))
        rootConfig[PostHogAutocaptureNoCapture] = true
        assertNull(ComposeInteractionTargetResolver.resolve(view, 20f, 20f, emptyList(), native, layout))
    }

    @Test
    fun `enabled child of disabled clickable parent is captured unless the path is excluded`() {
        rootConfig[SemanticsActions.OnClick] = AccessibilityAction(null) { true }
        rootConfig[SemanticsProperties.Disabled] = Unit
        assertEquals(2, assertNotNull(resolve()).semanticsId)
        rootConfig[PostHogAutocaptureNoCapture] = true
        assertNull(resolve())
        rootConfig[PostHogAutocaptureNoCapture] = false
        rootConfig[PostHogReplayMask] = true
        assertNull(resolve())
    }

    @Test
    fun `disabled clickable child does not fall back to enabled parent`() {
        childConfig[SemanticsActions.OnClick] = AccessibilityAction(null) { true }
        childConfig[SemanticsProperties.Disabled] = Unit
        assertNull(resolve())
    }

    @Test
    fun `disabled buttons and points outside clipped bounds are not targets`() {
        assertNotNull(resolve())
        assertNull(ComposeInteractionTargetResolver.resolve(view, 200f, 200f, emptyList()))
        buttonConfig[SemanticsProperties.Disabled] = Unit
        assertNull(resolve())
    }

    @Test
    fun `topmost semantic sibling wins and bounded traversal fails closed`() {
        val overlay =
            node(
                4,
                SemanticsConfiguration().apply {
                    this[SemanticsActions.OnClick] = AccessibilityAction(null) { true }
                    this[SemanticsProperties.Role] = Role.Switch
                },
            )
        whenever(root.children).thenReturn(listOf(button, overlay))
        whenever(overlay.parent).thenReturn(root)
        assertEquals(4, resolve()!!.semanticsId)
        assertEquals(2, resolve()!!.elements.first().nthChild)
        whenever(root.children).thenReturn(List(MAX_INTERACTION_NODES + 1) { overlay })
        assertNull(resolve())
    }

    private fun responseDigest(): ByteArray {
        val sink = InteractionResponseDigest(ByteArray(16))
        ComposeInteractionResponseSnapshot.append(view, sink, 0)
        return sink.finish()
    }

    @Test
    fun `response snapshots detect semantic content state layout and scroll without serializing them`() {
        var previous = responseDigest()
        val changes: List<() -> Unit> =
            listOf(
                { childConfig[SemanticsProperties.Text] = listOf(androidx.compose.ui.text.AnnotatedString("Changed")) },
                { childConfig[SemanticsProperties.StateDescription] = "Changed state" },
                { childConfig[SemanticsProperties.Selected] = true },
                { whenever(child.boundsInWindow).thenReturn(Rect(0f, 0f, 150f, 100f)) },
                {
                    childConfig[SemanticsProperties.VerticalScrollAxisRange] =
                        androidx.compose.ui.semantics.ScrollAxisRange(
                            { 10f },
                            { 100f },
                            false,
                        )
                },
            )
        for (change in changes) {
            change()
            val current = responseDigest()
            kotlin.test.assertFalse(previous.contentEquals(current))
            previous = current
        }
        kotlin.test.assertFalse(resolve()!!.elements.toString().contains("Changed"))
    }

    @Test
    fun `response snapshots never read excluded password or editable semantic content`() {
        val oversized = listOf(androidx.compose.ui.text.AnnotatedString("x".repeat(20000)))
        childConfig[SemanticsProperties.Text] = oversized
        kotlin.test.assertFailsWith<IllegalStateException> { responseDigest() }
        childConfig[PostHogAutocaptureNoCapture] = true
        responseDigest()
        childConfig[PostHogAutocaptureNoCapture] = false
        childConfig[PostHogReplayMask] = true
        responseDigest()
        childConfig[PostHogReplayMask] = false
        childConfig[SemanticsProperties.Password] = Unit
        responseDigest()
        val editable =
            SemanticsConfiguration().apply {
                this[SemanticsProperties.EditableText] = androidx.compose.ui.text.AnnotatedString("x".repeat(20000))
                this[SemanticsProperties.Text] = oversized
            }
        whenever(child.config).thenReturn(editable)
        responseDigest()
    }

    @Test
    fun `editable slider and scroll semantic actions are repetitive for detectors only`() {
        buttonConfig[SemanticsActions.SetProgress] = AccessibilityAction(null) { _: Float -> true }
        kotlin.test.assertTrue(resolve()!!.repetitive)
        // Ordinary semantic capture retains the same privacy-safe target.
        assertEquals("checkout_button", resolve()!!.elements.first().identifier)
    }
}

package com.posthog.android.surveys.compose.internal.ui

import androidx.compose.material3.MaterialTheme
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.hasSetTextAction
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithText
