package com.posthog.android.internal

import android.view.View
import androidx.compose.ui.layout.LayoutInfo
import androidx.compose.ui.node.RootForTest
import androidx.compose.ui.semantics.SemanticsActions
import androidx.compose.ui.semantics.SemanticsNode
import androidx.compose.ui.semantics.SemanticsProperties
import androidx.compose.ui.semantics.getOrNull
import com.posthog.android.PostHogAutocaptureNoCapture
import com.posthog.android.replay.PostHogMaskModifier.PostHogReplayMask

/** Called only for a verified Compose host; never stores semantics configurations or strings. */
@OptIn(androidx.compose.ui.ExperimentalComposeUiApi::class)
internal object ComposeInteractionResponseSnapshot {
    fun append(
        view: View,
        sink: InteractionResponseDigest,
        depth: Int,
    ): Set<LayoutInfo> {
        val owner = (view as? RootForTest)?.semanticsOwner ?: error("Unsupported semantics")
        val excludedLayouts = mutableSetOf<LayoutInfo>()

        fun visit(
            node: SemanticsNode,
            level: Int,
            excluded: Boolean,
        ) {
            sink.node(level)
            sink.number(node.id)
            val bounds = node.boundsInWindow
            sink.number(bounds.left.toBits())
            sink.number(bounds.top.toBits())
            sink.number(bounds.right.toBits())
            sink.number(bounds.bottom.toBits())
            val config = node.config
            val ignored =
                excluded || config.getOrNull(PostHogAutocaptureNoCapture) == true ||
                    config.getOrNull(PostHogReplayMask) == true || config.contains(SemanticsProperties.Password) ||
                    config.contains(SemanticsActions.SetText) || config.contains(SemanticsProperties.EditableText)
            if (ignored) excludedLayouts += node.layoutInfo
            sink.number(if (ignored) 1 else 0)
            sink.number(if (config.contains(SemanticsProperties.Disabled)) 1 else 0)
            sink.number(if (config.contains(SemanticsProperties.InvisibleToUser)) 1 else 0)
            if (!ignored) {
                config.getOrNull(SemanticsProperties.Text)?.forEach { sink.text(it.text) }
                config.getOrNull(SemanticsProperties.ContentDescription)?.forEach { sink.text(it) }
                sink.text(config.getOrNull(SemanticsProperties.StateDescription))
                sink.number(if (config.getOrNull(SemanticsProperties.Selected) == true) 1 else 0)
                sink.number(if (config.getOrNull(SemanticsProperties.Focused) == true) 1 else 0)
                sink.number(config.getOrNull(SemanticsProperties.ToggleableState)?.ordinal ?: -1)
                config.getOrNull(SemanticsProperties.ProgressBarRangeInfo)?.let { sink.number(it.current.toBits()) }
                config.getOrNull(SemanticsProperties.HorizontalScrollAxisRange)?.let { sink.number(it.value().toBits()) }
                config.getOrNull(SemanticsProperties.VerticalScrollAxisRange)?.let { sink.number(it.value().toBits()) }
            }
            val children = node.children
            check(children.size <= MAX_INTERACTION_NODES - sink.nodes)
            children.forEach { visit(it, level + 1, ignored) }
        }
        visit(owner.unmergedRootSemanticsNode, depth, false)
        return excludedLayouts
    }
}

package com.posthog.android.internal

import android.view.View
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.layout.LayoutInfo
import androidx.compose.ui.node.RootForTest
import androidx.compose.ui.semantics.Role
import androidx.compose.ui.semantics.SemanticsActions
import androidx.compose.ui.semantics.SemanticsNode
import androidx.compose.ui.semantics.SemanticsProperties
import androidx.compose.ui.semantics.getOrNull
import com.posthog.android.PostHogAutocaptureNoCapture
import com.posthog.android.replay.PostHogMaskModifier.PostHogReplayMask

/** Loaded only after checking for Compose; uses unmerged semantics to preserve subtree exclusions. */
@OptIn(androidx.compose.ui.ExperimentalComposeUiApi::class)
internal object ComposeInteractionTargetResolver {
    fun resolve(
        view: View,
        screenX: Float,
        screenY: Float,
        viewPath: List<View>,
        nativeTarget: InteractionTarget? = null,
        nativeLayoutInfo: LayoutInfo? = null,
    ): InteractionTarget? {
        val owner = (view as? RootForTest)?.semanticsOwner ?: return null
        val screen = IntArray(2)
        val window = IntArray(2)
        view.getLocationOnScreen(screen)
        view.getLocationInWindow(window)
        val point = Offset(screenX - screen[0] + window[0], screenY - screen[1] + window[1])
        var visited = 0
        var incomplete = false

        fun hit(
            node: SemanticsNode,
            depth: Int,
        ): List<SemanticsNode>? {
            if (++visited > MAX_INTERACTION_NODES || depth >= MAX_INTERACTION_DEPTH) {
                incomplete = true
                return null
            }
            val children = node.children
            if (children.size > MAX_INTERACTION_NODES - visited) {
                incomplete = true
                return null
            }
            // boundsInWindow is clipped by Compose. Children are in paint order.
            for (child in children.asReversed()) {
                hit(child, depth + 1)?.let { return listOf(node) + it }
                if (incomplete) return null
            }
            return if (node.boundsInWindow.contains(point)) listOf(node) else null
        }
        val path = hit(owner.unmergedRootSemanticsNode, 0) ?: return null
        if (incomplete ||
            path.any {
                it.config.getOrNull(PostHogAutocaptureNoCapture) == true ||
                    it.config.getOrNull(PostHogReplayMask) == true ||
                    it.config.contains(SemanticsProperties.Password)
            }
        ) {
            return null
        }
        if (nativeLayoutInfo != null && path.any { it.layoutInfo === nativeLayoutInfo }) return nativeTarget
        val nativeAncestor = nativeTarget?.view?.get()?.let { candidate -> viewPath.any { it === candidate } } == true
        if (nativeTarget != null && !nativeAncestor && nativeLayoutInfo == null) return null
        val targetIndex = path.indexOfLast { it.config.contains(SemanticsActions.OnClick) }
        if (targetIndex < 0) return nativeTarget.takeIf { nativeAncestor }
        if (path[targetIndex].config.contains(SemanticsProperties.Disabled)) return null
        val targetPath = path.take(targetIndex + 1)
        val elements =
            targetPath.asReversed().map { node ->
                val siblings = node.parent?.children ?: listOf(node)
                if (siblings.size > MAX_INTERACTION_NODES) return null
                val index = siblings.indexOfFirst { it.id == node.id }.coerceAtLeast(0)
                InteractionElement(
                    type = node.interactionType(),
                    identifier = node.config.getOrNull(SemanticsProperties.TestTag),
                    nthChild = index + 1,
                    nthOfType = siblings.take(index).count { it.interactionType() == node.interactionType() } + 1,
                )
            } + viewPath.asReversed().map { it.interactionElement() }
        val config = targetPath.last().config
        val repetitive =
            config.contains(SemanticsActions.SetText) || config.contains(SemanticsProperties.EditableText) ||
                config.contains(SemanticsActions.SetProgress) || config.contains(SemanticsActions.ScrollBy)
        return InteractionTarget(view, targetPath.last().id, elements.take(MAX_INTERACTION_ELEMENTS), repetitive)
    }

    // The native child tree has no Compose paint order. Match its holder to the winning layout
    // before returning a native target, so an overlaid Compose control cannot be misattributed.
    fun interopLayoutInfo(path: List<View>): LayoutInfo? =
        try {
            val holderClass = Class.forName(ANDROID_COMPOSE_VIEW_HOLDER_CLASS_NAME)
            val holder = path.lastOrNull { holderClass.isInstance(it) }
            holder?.let { holderClass.getMethod("getLayoutNode").invoke(it) as? LayoutInfo }
        } catch (_: Throwable) {
            null
        }

    private fun SemanticsNode.interactionType(): String =
        when (config.getOrNull(SemanticsProperties.Role)) {
            Role.Button -> "button"
            Role.Checkbox -> "checkbox"
            Role.Switch -> "switch"
            Role.RadioButton -> "radio"
            Role.Tab -> "tab"
            Role.Image -> "image"
            else -> "compose"
        }
}

package com.posthog

import com.posthog.internal.PostHogMemoryPreferences
import kotlin.test.AfterTest
import kotlin.test.Test
import kotlin.test.assertFalse
import kotlin.test.assertTrue

internal class PostHogIntegrationInstallFailureTest {
    private val testLogger = TestLogger()
    private var client: PostHogInterface? = null

    @AfterTest
    fun cleanup() {
        client?.close()
    }

    private fun getSut(failure: Throwable): FakePostHogIntegration {
        val healthy = FakePostHogIntegration()
        val broken =
            object : PostHogIntegration {
                override fun install(postHog: PostHogInterface) {
                    throw failure
                }
            }

        @Suppress("DEPRECATION")
        client =
            PostHog.with(
                PostHogConfig(API_KEY).apply {
                    logger = testLogger
                    cachePreferences = PostHogMemoryPreferences()
                    remoteConfig = false
                    preloadFeatureFlags = false
                    addBeforeSend { null }
                    addIntegration(broken)
                    addIntegration(healthy)
                },
            )
        return healthy
    }

    @Test
    fun `a missing artifact is reported as a warning that names the artifact`() {
        val healthy = getSut(NoClassDefFoundError("Failed resolution of: Lcurtains/Curtains;"))

        val warning = testLogger.warnings.single()
        assertTrue(warning.contains("com.squareup.curtains:curtains"))
        assertTrue(warning.contains("stay off for the whole process"))
        // one broken integration must not stop the others
        assertTrue(healthy.installed)
    }

    @Test
    fun `a missing curtains class in the cause is named as the artifact`() {
        val failure =
            NoClassDefFoundError(
                "Failed resolution of: Lcom/posthog/android/replay/PostHogReplayIntegration\$\$ExternalSyntheticLambda0;",
            ).apply { initCause(ClassNotFoundException("Didn't find class \"curtains.OnRootViewsChangedListener\"")) }

        getSut(failure)

        assertTrue(testLogger.warnings.single().contains("com.squareup.curtains:curtains"))
    }

    @Test
    fun `a missing class of an unknown artifact is still reported as a warning`() {
        getSut(ClassNotFoundException("com.example.Missing"))

        assertTrue(testLogger.warnings.single().contains("probably excludes an artifact"))
    }

    @Test
    fun `a static initializer failure is not blamed on a missing artifact`() {
        getSut(ExceptionInInitializerError(IllegalStateException("boom")))

        assertTrue(testLogger.warnings.isEmpty())
        assertFalse(testLogger.messages.any { it.contains("artifact") })
    }

    @Test
    fun `any other install failure stays a debug message`() {
        getSut(RuntimeException("boom"))

        assertTrue(testLogger.warnings.isEmpty())
        assertTrue(testLogger.messages.any { it.contains("failed to install") })
        assertFalse(testLogger.messages.any { it.contains("artifact") })
    }
}

